  const fiberHinges=activeFiberHinges(project),fiberHingeCount=fiberHinges.length,hasFiberHinges=fiberHingeCount>0,cyclicFiberHingeCount=fiberHinges.filter((h:any)=>!!h.config?.cyclic).length;
