  const importGroundMotion=(file:File,axis:'x'|'y'='x')=>{const reader=new FileReader();reader.onload=()=>{const pts=parseGroundMotionCsv(String(reader.result||''));if(axis==='x'&&pts.x.length>=2)setDynamicGroundMotionText(pts.x.map(x=>`${x.t}:${x.accelG}`).join(', '));if(axis==='y'){const src=pts.y.length>=2?pts.y:pts.x;if(src.length>=2)setDynamicGroundMotionTextY(src.map(x=>`${x.t}:${x.accelG}`).join(', '))}else if(pts.y.length>=2){setDynamicGroundMotionTextY(pts.y.map(x=>`${x.t}:${x.accelG}`).join(', '));setDynamicGroundMotionDirection('xy')}};reader.readAsText(file)};
